 if(p.startsWith('/backend/')||p.startsWith('/admin-backend/')||p.startsWith('/api/')||p.startsWith('/media/'))return community(req,env,p);
 if(!['GET','HEAD'].includes(req.method))return response('Método no permitido','text/plain',405);
 const assets={'/catalogo.js':[CATALOG_JS,'application/javascript'],'/catalogo.css':[CATALOG_CSS,'text/css'],'/guardian.js':[GUARDIAN_JS,'application/javascript'],'/guardian.css':[GUARDIAN_CSS,'text/css'],'/economia-admin.js':[ECONOMY_ADMIN_JS,'application/javascript'],'/economia-admin.css':[ECONOMY_ADMIN_CSS,'text/css'],'/admin.css':[SHELL_CSS,'text/css'],'/admin.js':[SHELL_JS,'application/javascript'],'/panel.css':[PANEL_CSS,'text/css'],'/panel.js':[PANEL_JS,'application/javascript'],'/_uhz/admin-bridge.js':[ADMIN_BRIDGE,'application/javascript'],'/_uhz/admin-store.js':[ADMIN_STORE_JS,'application/javascript'],'/_uhz/admin-store.css':[ADMIN_STORE_CSS,'text/css'],'/_uhz/creadores/app.js':[CREATOR_JS,'application/javascript'],'/_uhz/creadores/style.css':[CREATOR_CSS,'text/css'],'/_uhz/licencias/app.js':[LICENSE_JS,'application/javascript'],'/_uhz/licencias/style.css':[LICENSE_CSS,'text/css']};
 if(assets[p]){const etag='W/"cleanup-20261029-1-'+p+'"';const res=response(req.method==='HEAD'?null:assets[p][0],assets[p][1]+'; charset=utf-8');res.headers.set('Cache-Control','private,max-age=300');res.headers.set('ETag',etag);if(req.headers.get('if-none-match')===etag)return new Response(null,{status:304,headers:res.headers});return res;}
 if(['/app.js','/style.css','/upgrade.js','/upgrade.css'].includes(p))return community(req,env,p);
 if(p==='/'||p==='/index.html'||p==='/control'){const res=response(req.method==='HEAD'?null:LEGACY_HTML);res.headers.set('Content-Security-Policy',"default-src 'self'; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net; style-src 'self' 'unsafe-inline'; img-src 'self' https: data: blob:; connect-src 'self'; frame-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'");return res;}
 if(p==='/favicon.ico')return Response.redirect('https://univershzrw.com/favicon.ico',302);
 const isAuth=['/iniciar-sesion','/recuperar-contrasena','/nueva-contrasena','/verificar-cuenta'].includes(p);
 let guard;if(!isAuth){guard=await protect(req,env);if(guard.denied)return guard.denied;}
 if(p==='/catalogo')return cookies(guard.auth,response(req.method==='HEAD'?null:CATALOG_HTML));
 if(p==='/economia/administrar')return cookies(guard.auth,response(req.method==='HEAD'?null:ECONOMY_ADMIN_HTML));
