 if(p==='/legacy'||p.startsWith('/_uhz/admin/')){const res=response(LEGACY_HTML);res.headers.set('Content-Security-Policy',"default-src 'self'; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net; style-src 'self' 'unsafe-inline'; img-src 'self' https: data: blob:; connect-src 'self'; frame-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'");return cookies(guard.auth,res);}
 if(p==='/creadores'||p.startsWith('/licencias')){let html=p.startsWith('/licencias')?LICENSE_HTML:CREATOR_HTML;html=html.replace('</head>','<link rel="stylesheet" href="/panel.css"></head>');return cookies(guard.auth,response(html));}
